Texture2D g_modelBaseColor : register(t6);
Texture2D g_modelMetalRough : register(t7);
SamplerState g_sampler : register(s0);

cbuffer cbEffect : register(b0)
{
    float g_time;
    float g_audioBass;
    float g_audioMid;
    float g_audioTreble;
    float4 g_params[16];
};

cbuffer cbRaymarchCamera : register(b3)
{
    float3 g_camPos;
    float  _camPad;
    row_major float4x4 g_invViewProj; 
    row_major float4x4 g_viewProj;
};


cbuffer cbMaterial : register(b5)
{
    float4 g_baseColorRate;
    float  g_metallicRate;
    float  g_roughnessRate;
	float  g_hasNormalMap;   
    float _matPad;
};

float4 node6_func(float4 color, float saturation)
{
static const float3 LumCoeff = float3(0.2126, 0.7152, 0.0722);

float luminance = dot(color.rgb, LumCoeff);
float3 grayColor = float3(luminance, luminance, luminance);

float3 result = lerp(grayColor, color.rgb, saturation);
return float4(result, color.a);
}


struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

struct PS_OUT {
    float4 target0 : SV_Target0;
    float4 target1 : SV_Target1;
    float4 target2 : SV_Target2;
    float4 target3 : SV_Target3;
    float4 target4 : SV_Target4;
};

PS_OUT main(PS_IN In)
{
    float4 node8_out = (g_modelBaseColor.Sample(g_sampler, In.uv) * g_baseColorRate);
    float node7_out = 1.030000f;
    float4 node6_out = node6_func(node8_out, node7_out);
    float4 node10_out = g_params[0];
    float node11_out = 1.000000f;
    float node12_out = 0.210000f;
    float3 ssh9_N = normalize(In.worldNormal);
    float3 ssh9_T = normalize(In.worldTangent - dot(In.worldTangent, ssh9_N) * ssh9_N);
    float3 ssh9_B = cross(ssh9_N, ssh9_T);
    float3x3 ssh9_TBN = float3x3(ssh9_T, ssh9_B, ssh9_N);
    float3 ssh9_Lw = normalize(((node10_out).xyz));
    float3 ssh9_Lt = mul(ssh9_TBN, ssh9_Lw);
    float ssh9_h0 = dot(g_modelBaseColor.Sample(g_sampler, In.uv).rgb, float3(0.299,0.587,0.114));
    float ssh9_shadow = 1.0;
    float2 ssh9_uvStep = ssh9_Lt.xy * (node12_out) * 0.01;
    [unroll] for (int ssh9_i = 1; ssh9_i <= 8; ++ssh9_i)
    {
        float2 ssh9_suv = In.uv + ssh9_uvStep * ssh9_i;
        float ssh9_hs = dot(g_modelBaseColor.Sample(g_sampler, ssh9_suv).rgb, float3(0.299,0.587,0.114));
        float ssh9_expected = ssh9_h0 + ssh9_Lt.z * ssh9_i * 0.05;
        if (ssh9_hs > ssh9_expected)
            ssh9_shadow = min(ssh9_shadow, 1.0 - (ssh9_hs - ssh9_expected) * 5.0);
    }
    ssh9_shadow = saturate(lerp(1.0, ssh9_shadow, (node11_out)));
    float3 ssh9_result = (node6_out).rgb * ssh9_shadow;
    float4 node9_out = float4(ssh9_result, (node6_out).a);
    float node14_out = 0.020000f;
    float nfh13_str = node14_out;
    float3 nfh13_rawN = In.worldNormal;
    float  nfh13_lenN = length(nfh13_rawN);
    float3 nfh13_N = (nfh13_lenN > 1e-5) ? (nfh13_rawN / nfh13_lenN) : float3(0.0, 1.0, 0.0);
    float3 nfh13_rawT = In.worldTangent - dot(In.worldTangent, nfh13_N) * nfh13_N;
    float  nfh13_lenT = length(nfh13_rawT);
    float3 nfh13_fb = (abs(nfh13_N.y) < 0.99) ? float3(0.0, 1.0, 0.0) : float3(1.0, 0.0, 0.0);
    float3 nfh13_T = (nfh13_lenT > 1e-5) ? (nfh13_rawT / nfh13_lenT) : normalize(cross(nfh13_fb, nfh13_N));
    float3 nfh13_B = cross(nfh13_N, nfh13_T);
    float4 nfh13_col = node9_out;
    float nfh13_h = dot(nfh13_col.rgb, float3(0.2126, 0.7152, 0.0722)) * nfh13_str;
    float3 nfh13_dpdx = ddx(In.worldPos);
    float3 nfh13_dpdy = ddy(In.worldPos);
    float3 nfh13_R1 = cross(nfh13_dpdy, nfh13_N);
    float3 nfh13_R2 = cross(nfh13_N, nfh13_dpdx);
    float  nfh13_det = dot(nfh13_dpdx, nfh13_R1);
    float3 nfh13_grad = sign(nfh13_det) * (ddx(nfh13_h) * nfh13_R1 + ddy(nfh13_h) * nfh13_R2);
    float3 nfh13_result = normalize(abs(nfh13_det) * nfh13_N - nfh13_grad);
    float3 nfh13_texN = float3(dot(nfh13_result, nfh13_T), dot(nfh13_result, nfh13_B), dot(nfh13_result, nfh13_N));
    float3 node13_out = nfh13_result;
    float4 node15_out = float4(0.042520f, 0.062500f, 0.010938f, 1.000000f);
    float4 node17_out = float4(0.000000f, 0.000000f, 0.000000f, 1.000000f);
    float node19_out = 1.000000f;
    PS_OUT o;
    o.target0 = float4((node9_out).xyz, (g_modelMetalRough.Sample(g_sampler, In.uv).b * g_metallicRate));
    o.target1 = float4((nfh13_result) * 0.5 + 0.5, (g_modelMetalRough.Sample(g_sampler, In.uv).g * g_roughnessRate));
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node15_out).xyz, node19_out);
    o.target4 = node17_out;
    return o;
}

